import React, { useEffect, useMemo, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import Loader from '../common/stateHandlers/LoaderState';
import ErrorMessage from '../common/stateHandlers/ErrorState';
import { getCalendarForMonth, getTournamentDetails } from '../services/tennisApiService';

const PAGE_SIZE = 20;

const MONTHS = [
  { value: 1, label: 'January' },
  { value: 2, label: 'February' },
  { value: 3, label: 'March' },
  { value: 4, label: 'April' },
  { value: 5, label: 'May' },
  { value: 6, label: 'June' },
  { value: 7, label: 'July' },
  { value: 8, label: 'August' },
  { value: 9, label: 'September' },
  { value: 10, label: 'October' },
  { value: 11, label: 'November' },
  { value: 12, label: 'December' },
];

function readTournamentName(payload, fallbackId) {
  if (!payload || typeof payload !== 'object') {
    return `Tournament ${fallbackId}`;
  }

  const candidate = payload.tournament || payload.data || payload;
  return (
    candidate.name ||
    candidate.shortName ||
    candidate.fullName ||
    candidate.slug ||
    `Tournament ${fallbackId}`
  );
}

function extractTournaments(payload) {
  if (!payload || typeof payload !== 'object') {
    return [];
  }

  const daily = Array.isArray(payload.dailyUniqueTournaments) ? payload.dailyUniqueTournaments : [];
  const byId = new Map();

  daily.forEach((dayItem) => {
    const date = dayItem?.date || '';
    const ids = Array.isArray(dayItem?.uniqueTournamentIds) ? dayItem.uniqueTournamentIds : [];

    ids.forEach((id) => {
      if (!byId.has(id)) {
        byId.set(id, {
          id,
          days: 0,
          firstDate: date,
          lastDate: date,
        });
      }

      const row = byId.get(id);
      row.days += 1;
      row.lastDate = date || row.lastDate;
    });
  });

  return Array.from(byId.values()).sort((a, b) => {
    if (b.days !== a.days) return b.days - a.days;
    return a.id - b.id;
  });
}

export default function TournamentHubList() {
  const [searchParams, setSearchParams] = useSearchParams();

  const today = useMemo(() => new Date(), []);
  const currentMonth = today.getMonth() + 1;
  const currentYear = today.getFullYear();

  const queryMonth = Number(searchParams.get('month'));
  const queryYear = Number(searchParams.get('year'));

  const selectedMonth = Number.isFinite(queryMonth) && queryMonth >= 1 && queryMonth <= 12 ? queryMonth : currentMonth;
  const selectedYear = Number.isFinite(queryYear) && queryYear >= 2020 && queryYear <= currentYear + 1 ? queryYear : currentYear;

  const [loading, setLoading] = useState(true);
  const [loadingNames, setLoadingNames] = useState(false);
  const [error, setError] = useState('');
  const [tournaments, setTournaments] = useState([]);
  const [nameMap, setNameMap] = useState({});
  const [page, setPage] = useState(1);

  const yearOptions = useMemo(() => {
    const years = [];
    for (let y = currentYear + 1; y >= 2020; y -= 1) {
      years.push(y);
    }
    return years;
  }, [currentYear]);

  useEffect(() => {
    let cancelled = false;

    const loadMonth = async () => {
      setLoading(true);
      setError('');

      try {
        const payload = await getCalendarForMonth(selectedMonth, selectedYear);
        if (cancelled) return;
        setTournaments(extractTournaments(payload));
        setPage(1);
      } catch (err) {
        if (!cancelled) {
          setError(err.message || 'Failed to load tournaments for selected month.');
          setTournaments([]);
        }
      } finally {
        if (!cancelled) {
          setLoading(false);
        }
      }
    };

    loadMonth();
    return () => {
      cancelled = true;
    };
  }, [selectedMonth, selectedYear]);

  const totalPages = Math.max(1, Math.ceil(tournaments.length / PAGE_SIZE));
  const visibleTournaments = useMemo(() => {
    const start = (page - 1) * PAGE_SIZE;
    return tournaments.slice(start, start + PAGE_SIZE);
  }, [tournaments, page]);

  const unresolvedIds = useMemo(() => {
    return visibleTournaments
      .map((item) => item.id)
      .filter((id) => !nameMap[id]);
  }, [visibleTournaments, nameMap]);

  useEffect(() => {
    if (unresolvedIds.length === 0) return;

    let cancelled = false;

    const loadNames = async () => {
      setLoadingNames(true);
      const nextMap = {};

      for (const id of unresolvedIds) {
        try {
          const result = await getTournamentDetails(id);
          if (cancelled) return;
          nextMap[id] = readTournamentName(result, id);
        } catch (_err) {
          // Keep fallback label when details endpoint is throttled.
        }
      }

      if (Object.keys(nextMap).length > 0) {
        setNameMap((prev) => ({ ...prev, ...nextMap }));
      }
      setLoadingNames(false);
    };

    loadNames();
    return () => {
      cancelled = true;
    };
  }, [unresolvedIds]);

  const handleMonthChange = (event) => {
    const month = event.target.value;
    const next = new URLSearchParams(searchParams);
    next.set('month', month);
    next.set('year', String(selectedYear));
    setSearchParams(next, { replace: true });
  };

  const handleYearChange = (event) => {
    const year = event.target.value;
    const next = new URLSearchParams(searchParams);
    next.set('month', String(selectedMonth));
    next.set('year', year);
    setSearchParams(next, { replace: true });
  };

  return (
    <div className="space-y-6 p-4 md:p-6">
      <div className="rounded-xl border border-slate-700 bg-slate-900 p-4">
        <div className="flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
          <div>
            <h1 className="text-2xl font-bold text-white">Tournament Hub</h1>
            <p className="mt-1 text-sm text-slate-400">Browse monthly tournaments and open detailed tournament pages.</p>
          </div>

          <div className="flex flex-wrap gap-3">
            <div>
              <label htmlFor="month-filter" className="mb-1 block text-xs uppercase tracking-wide text-slate-400">Month</label>
              <select
                id="month-filter"
                value={selectedMonth}
                onChange={handleMonthChange}
                className="rounded-lg border border-slate-600 bg-slate-800 px-3 py-2 text-slate-100"
              >
                {MONTHS.map((month) => (
                  <option key={month.value} value={month.value}>{month.label}</option>
                ))}
              </select>
            </div>

            <div>
              <label htmlFor="year-filter" className="mb-1 block text-xs uppercase tracking-wide text-slate-400">Year</label>
              <select
                id="year-filter"
                value={selectedYear}
                onChange={handleYearChange}
                className="rounded-lg border border-slate-600 bg-slate-800 px-3 py-2 text-slate-100"
              >
                {yearOptions.map((year) => (
                  <option key={year} value={year}>{year}</option>
                ))}
              </select>
            </div>
          </div>
        </div>
      </div>

      {error ? <ErrorMessage message={error} /> : null}

      <div className="rounded-xl border border-slate-700 bg-slate-900 p-4">
        <div className="mb-3 flex items-center justify-between">
          <h2 className="text-lg font-semibold text-white">Tournament List</h2>
          <span className="text-sm text-slate-400">{tournaments.length} tournaments</span>
        </div>

        {loading ? (
          <Loader />
        ) : (
          <div className="overflow-auto">
            <table className="min-w-full text-sm text-slate-200">
              <thead>
                <tr className="border-b border-slate-700 text-left text-xs uppercase text-slate-400">
                  <th className="py-2 pr-3">Tournament</th>
                  <th className="py-2 pr-3">ID</th>
                  <th className="py-2 pr-3">Days In Month</th>
                  <th className="py-2 pr-3">Last Seen</th>
                  <th className="py-2 pr-3">Open</th>
                </tr>
              </thead>
              <tbody>
                {tournaments.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="py-3 text-slate-400">No tournaments found for selected month/year.</td>
                  </tr>
                ) : (
                  visibleTournaments.map((item) => (
                    <tr key={item.id} className="border-b border-slate-800/70">
                      <td className="py-2 pr-3">{nameMap[item.id] || `Tournament ${item.id}`}</td>
                      <td className="py-2 pr-3">{item.id}</td>
                      <td className="py-2 pr-3">{item.days}</td>
                      <td className="py-2 pr-3">{item.lastDate || '-'}</td>
                      <td className="py-2 pr-3">
                        <Link className="text-cyan-300 hover:text-cyan-200" to={`/tournament/${item.id}`}>
                          View
                        </Link>
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        )}

        {tournaments.length > 0 ? (
          <div className="mt-4 flex items-center justify-between">
            <span className="text-xs text-slate-400">Page {page} of {totalPages}</span>
            <div className="flex gap-2">
              <button
                className="rounded border border-slate-600 px-3 py-1 text-xs text-slate-200 disabled:opacity-40"
                disabled={page <= 1}
                onClick={() => setPage((current) => Math.max(1, current - 1))}
              >
                Prev
              </button>
              <button
                className="rounded border border-slate-600 px-3 py-1 text-xs text-slate-200 disabled:opacity-40"
                disabled={page >= totalPages}
                onClick={() => setPage((current) => Math.min(totalPages, current + 1))}
              >
                Next
              </button>
            </div>
          </div>
        ) : null}

        {loadingNames ? <p className="mt-2 text-xs text-slate-500">Resolving tournament names...</p> : null}
      </div>
    </div>
  );
}
